              onProblemChange={handleFilterChange}
              onPageChange={handlePageChange}
              onRefresh={fetchSubmissions}
            />

            <SubmissionsStats
              accepted={acceptedCount}
              incorrect={incorrectCount}
              total={totalSubmissions}
            />
          </div>
        </div>
      </div>
