import { CheckCircle2 } from 'lucide-react'
import { Badge } from '@/components/common'
import { DataTable } from '@/components/tables'
import type { ContestProblem } from '../types'

const stateTone = (state: string) => {
  const normalized = state.toLowerCase()
  if (normalized === 'aceptado') return 'success' as const
  if (normalized.includes('incorrecta')) return 'danger' as const
  if (normalized.includes('limit')) return 'warning' as const
  return 'neutral' as const
}

export function ProblemsTable({ problems }: { problems: ContestProblem[] }) {
  return (
    <DataTable
      rows={problems}
      emptyText="Este concurso todavía no tiene problemas disponibles."
      classNames={{
        container:
          'overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-xs',
        table: 'min-w-[680px] text-left text-sm',
        thead: 'border-b border-slate-200 bg-slate-50/80',
        headerCell:
          'px-5 py-3.5 text-xs font-bold uppercase tracking-wider text-slate-500',
        row: 'border-b border-slate-100/70 transition-colors hover:bg-slate-50/60 last:border-b-0',
        cell: 'px-5 py-4 align-middle text-slate-700',
        emptyCell: 'px-6 py-12 text-center',
      }}
      columns={[
        {
          key: 'inciso',
          header: 'INCISO',
          render: (problem) => <strong className="text-slate-900">{problem.inciso}</strong>,
        },
        {
          key: 'titulo',
          header: 'PROBLEMA',
          render: (problem) => <span className="font-medium text-slate-900">{problem.titulo}</span>,
        },
        { key: 'tiempo', header: 'TIEMPO', render: (problem) => `${problem.tiempo} ms` },
        { key: 'memoria', header: 'MEMORIA', render: (problem) => `${problem.memoria} MB` },
        { key: 'intentos', header: 'INTENTOS' },
        {
          key: 'estado',
          header: 'ESTADO',
          render: (problem) => (
            <Badge tone={stateTone(problem.estado)} className="gap-1">
              {problem.resuelto && <CheckCircle2 className="size-3" aria-hidden="true" />}
              {problem.estado}
            </Badge>
          ),
        },
      ]}
    />
  )
}

import { useEffect, useState } from 'react'
import { BookOpen, ExternalLink, Send } from 'lucide-react'
import { Link, useParams } from 'react-router-dom'
import { Alert, Button, Card, LinkButton, Spinner } from '@/components/common'
import { UserLayout } from '@/layouts/UserLayout'
import { routes } from '@/routes/constants'
import { ProblemsTable } from '../components/ProblemsTable'
import { getContestDashboard } from '../service'
import type { ContestDashboard } from '../types'

export default function ContestProblemsPage() {
  const { contestCode } = useParams<{ contestCode: string }>()
  const [dashboard, setDashboard] = useState<ContestDashboard | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!contestCode) {
      setError('El código del concurso es obligatorio.')
      return
    }
    let active = true
    setDashboard(null)
    setError(null)
    void getContestDashboard(contestCode)
      .then((result) => {
        if (active) setDashboard(result ?? null)
      })
      .catch(() => {
        if (active) setError('No se pudo cargar el dashboard del concurso.')
      })
    return () => {
      active = false
    }
  }, [contestCode])

  return (
    <UserLayout>
      <main className="mx-auto w-full max-w-screen-2xl space-y-6 px-4 py-6 sm:px-6 lg:px-8">
        {error && <Alert tone="danger">{error}</Alert>}
        {!error && !dashboard && <Spinner label="Cargando concurso" />}
        {dashboard && (
          <>
            <Card className="space-y-5">
              <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                <div>
                  <p className="text-sm font-semibold text-slate-500">{dashboard.codigo}</p>
                  <h1 className="text-2xl font-bold text-slate-900">{dashboard.nombre}</h1>
                  <p className="mt-1 text-sm text-slate-600">
                    {dashboard.problemasResueltos} de {dashboard.totalProblemas} problemas resueltos · {dashboard.intentosTotales} intentos
                  </p>
                </div>
                <div className="flex flex-wrap gap-2">
                  {dashboard.urlSetProblemas ? (
                    <LinkButton
                      href={dashboard.urlSetProblemas}
                      target="_blank"
                      rel="noopener noreferrer"
                      variant="primary"
                      leftIcon={<ExternalLink className="size-4" />}
                    >
                      Ver PDF
                    </LinkButton>
                  ) : (
                    <Button disabled leftIcon={<ExternalLink className="size-4" />}>
                      PDF no disponible
                    </Button>
                  )}
                </div>
              </div>
              <nav aria-label="Navegación del concurso" className="flex gap-5 border-b border-slate-200 text-sm font-semibold">
                <span className="flex items-center gap-2 border-b-2 border-slate-900 pb-3 text-slate-900">
                  <BookOpen className="size-4" /> Problemas
                </span>
                <Link className="flex items-center gap-2 pb-3 text-slate-500 hover:text-slate-900" to={routes.studentContestSubmissions(dashboard.codigo)}>
                  <Send className="size-4" /> Mis envíos
                </Link>
              </nav>
            </Card>
            <Card className="space-y-4">
              <div>
                <h2 className="text-lg font-bold text-slate-900">Set de problemas</h2>
                <p className="text-sm text-slate-600">Consultá los incisos disponibles y su progreso.</p>
              </div>
              <ProblemsTable problems={dashboard.problemas} />
            </Card>
          </>
        )}
      </main>
    </UserLayout>
  )
}

